package com.bank.repair.service;

import com.bank.repair.model.TxnNode;
import java.util.logging.Logger;

// Locates the node where a cycle begins, using constant extra space.
public class CycleEntryLocator {
    private static final Logger log = Logger.getLogger(CycleEntryLocator.class.getName());

    public TxnNode findCycleStart(TxnNode head) {
        TxnNode slow = head;
        TxnNode fast = head;

        // Phase 1: detect a meeting point inside the loop.
        boolean cyclic = false;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) { cyclic = true; break; }
        }
        if (!cyclic) {
            log.info("No cycle; no entry node.");
            return null;
        }

        // Phase 2: reset one pointer to head, advance both one step at a time.
        TxnNode ptr = head;
        while (ptr != slow) {
            ptr = ptr.next;
            slow = slow.next;
        }
        final String entryId = ptr.id;
        log.severe(() -> "Cycle starts at record " + entryId);
        return ptr;
    }
}
