package com.bank.repair;

import com.bank.repair.model.TxnNode;
import com.bank.repair.service.CycleEntryLocator;
import java.util.logging.Logger;

public class CycleEntryDemo {
    private static final Logger log = Logger.getLogger(CycleEntryDemo.class.getName());

    public static void main(String[] args) {
        // Chain: T1 -> T2 -> T3 -> T4 -> T5 -> back to T3 (loop entry at T3)
        TxnNode t1 = new TxnNode("T1");
        TxnNode t2 = new TxnNode("T2");
        TxnNode t3 = new TxnNode("T3");
        TxnNode t4 = new TxnNode("T4");
        TxnNode t5 = new TxnNode("T5");
        t1.next = t2; t2.next = t3; t3.next = t4; t4.next = t5;
        t5.next = t3; // corrupted pointer creates the loop

        CycleEntryLocator locator = new CycleEntryLocator();
        TxnNode entry = locator.findCycleStart(t1);

        log.info(() -> "Loop entry record = " + (entry == null ? "none" : entry.id));
    }
}
